func captureArea() {
    if !Thread.isMainThread {
        DispatchQueue.main.async { [weak self] in
            self?.captureArea()
        }
        return
    }

    guard canStartAreaCapture() else {
        return
    }

    isCaptureInProgress = true
    Task { [weak self] in
        guard let self else { return }
        do {
            let image = try await NativeAreaCapture.capture()
            try await MainActor.run {
                defer { self.isCaptureInProgress = false }
                guard let image else { return }
                // The pointer remains on the display where selection finished.
                let screen = self.screenUnderMouse() ?? NSScreen.main ?? NSScreen.screens.first
                guard let displayID = screen?.displayID else { return }
                try self.finishCapture(with: image, onDisplayID: displayID)
            }
        } catch {
            await MainActor.run {
                self.isCaptureInProgress = false
                self.handleCaptureFailure(error)
            }
        }
    }
}

/// Captures the full contents of the display under the mouse.
func captureFullScreen() {
    if !Thread.isMainThread {
        DispatchQueue.main.async { [weak self] in
            self?.captureFullScreen()
        }
        return
    }

    guard canStartFullScreenCapture() else {
        return
    }
    guard let screen = screenUnderMouse() ?? menuBarScreen() ?? NSScreen.main ?? NSScreen.screens.first else {
        return
    }

    captureRegion(in: screen.frame, on: screen)
}

/// Starts the rename/note flow for an already-saved image.
func beginPostCaptureFlow(forExistingFileAt url: URL, on screen: NSScreen? = nil, escapeKeyDeletesFile: Bool = true) {
    beginPostCaptureFlow(forExistingFileAt: url,
                         initialImage: nil,
                         initialFilePersistence: nil,
                         initialScreenshotCounter: nil,
                         on: screen,
                         escapeKeyDeletesFile: escapeKeyDeletesFile)
}

func beginPostCaptureFlow(forExistingFileAt url: URL,
                          initialImage: NSImage? = nil,
                          initialFilePersistence: Task<URL, Error>? = nil,
                          initialScreenshotCounter: Int? = nil,
                          on screen: NSScreen? = nil,
                          escapeKeyDeletesFile: Bool = true) {
    if !Thread.isMainThread {
        DispatchQueue.main.async { [weak self] in
            self?.beginPostCaptureFlow(forExistingFileAt: url,
                                       initialImage: initialImage,
                                       initialFilePersistence: initialFilePersistence,
                                       initialScreenshotCounter: initialScreenshotCounter,
                                       on: screen,
                                       escapeKeyDeletesFile: escapeKeyDeletesFile)
        }
        return
    }

    guard activeWorkflow == nil else { return }

    if initialImage == nil {
        switch ImageSafety.inspectFile(at: url) {
        case .tooLarge:
            presentError(
                title: "Image is too large",
                message: "This image is too large to open safely."
            )
            return
        case .notAnImage, .safe:
            break
        }
    }

    let workflow = ScreenshotWorkflowController(
        fileURL: url,
        initialImage: initialImage,
        initialFilePersistence: initialFilePersistence,
        initialScreenshotCounter: initialScreenshotCounter,
        settingsStore: settingsStore,
        clipboardService: clipboardService,
        backupService: backupService,
        sourceScreen: screen,
        escapeKeyDeletesFile: escapeKeyDeletesFile
    )

    workflow.onFinish = { [weak self] in
        self?.activeWorkflow = nil
    }

    activeWorkflow = workflow
    workflow.start()
}

var isBusyForUserCommands: Bool {
    isCaptureInProgress || activeWorkflow != nil
}

/// Saves an arbitrary image to the Desktop using the current settings
/// (maxWidth, filename template) and returns the resulting URL.
func saveImageToDesktop(_ image: NSImage) throws -> URL {
    let prepared = try prepareCaptureSave(for: image)
    return try persistPreparedCapture(prepared)
}

// MARK: - Capture pipeline

private func canStartNewCapture() -> Bool {
    if isCaptureInProgress {
        return false
    }
    if activeWorkflow != nil {
        return false
    }
    return true
}

func canStartAreaCapture() -> Bool {
    return canStartNewCapture()
}

func canStartFullScreenCapture() -> Bool {
    canStartNewCapture()
}

private func captureRegion(in rect: CGRect, on screen: NSScreen) {
    if !Thread.isMainThread {
        let screenID = screen.displayID
        DispatchQueue.main.async { [weak self] in
            guard let self else { return }
            let targetScreen = self.screenForDisplayID(screenID) ?? NSScreen.main ?? NSScreen.screens.first
            guard let targetScreen else { return }
            self.captureRegion(in: rect, on: targetScreen)
        }
        return
    }

    guard !isCaptureInProgress else { return }
    guard let displayID = screen.displayID else {
        presentError(title: "Screenshot failed", message: "Unable to determine display ID.")
        return
    }

    let snapshot = ScreenSnapshot(displayID: displayID,
                                  frame: screen.frame,
                                  scale: screen.backingScaleFactor)
    isCaptureInProgress = true

    Task { [weak self] in
        guard let self else { return }

        do {
            let cgImage = try await self.captureCGImage(rect: rect, on: snapshot)
            try await MainActor.run {
                defer { self.isCaptureInProgress = false }
                try self.finishCapture(with: cgImage, onDisplayID: snapshot.displayID)
            }
        } catch {
            await MainActor.run {
                self.isCaptureInProgress = false
                self.handleCaptureFailure(error)
            }
        }
    }
}

private func finishCapture(with cgImage: CGImage, onDisplayID displayID: CGDirectDisplayID) throws {
    let imageSize = NSSize(width: CGFloat(cgImage.width), height: CGFloat(cgImage.height))
    let image = NSImage(cgImage: cgImage, size: imageSize)
    let preparedSave = try prepareCaptureSave(for: image)
    let initialFilePersistence = makeInitialFilePersistenceTask(for: preparedSave)
    beginPostCaptureFlow(forExistingFileAt: preparedSave.targetURL,
                         initialImage: preparedSave.image,
                         initialFilePersistence: initialFilePersistence,
                         initialScreenshotCounter: preparedSave.currentCounter,
                         on: screenForDisplayID(displayID))
    soundPlayer.playCaptureSound()
}

private func triggerAreaScreenshot() {
    if settingsWindowController?.isRecordingAnyShortcut == true {
        return
    }
    if isVideoRenameBusy {
        return
    }
    if isScratchpadBusyOrOpening {
        return
    }
    if recordingService.isBusyForUserCommands {
        return
    }
    screenshotService.captureArea()
}

private func triggerFullScreenshot() {
    if settingsWindowController?.isRecordingAnyShortcut == true {
        return
    }
    if isVideoRenameBusy {
        return
    }
    if isScratchpadBusyOrOpening {
        return
    }
    if recordingService.isBusyForUserCommands {
        return
    }
    screenshotService.captureFullScreen()
}

private func triggerReopenFinderSelection() {
    if settingsWindowController?.isRecordingAnyShortcut == true {
        return
    }
    if isVideoRenameBusy {
        return
    }
    if isScratchpadBusyOrOpening {
        return
    }
    if recordingService.isBusyForUserCommands {
        return
    }
    if screenshotService.isBusyForUserCommands {
        return
    }

    finderSelectionLookup.requestSelection { [weak self] result in
        self?.handleFinderSelectionResult(result)
    }
}

private func handleFinderSelectionResult(_ result: Result<FinderSelectionService.Selection, Error>) {
    switch result {
    case .success(let selection):
        let url: URL
        switch selection {
        case .none:
            presentError(title: "No Finder Selection", message: "Select an image file in Finder, then press the shortcut again.")
            return
        case .multiple(let count):
            presentError(title: "Multiple Finder Items Selected", message: "Select exactly 1 image file in Finder (you selected \(count)), then press the shortcut again.")
            return
        case .single(let selectedURL):
            url = selectedURL
        }
        switch ImageSafety.inspectFile(at: url) {
        case .tooLarge:
            presentError(
                title: "Image is too large",
                message: "This image is too large to open safely. Choose a smaller screenshot and try again."
            )
            return
        case .notAnImage:
            presentError(title: "Not an Image", message: "The selected Finder item is not a readable image.")
            return
        case .safe:
            break
        }

        screenshotService.beginPostCaptureFlow(forExistingFileAt: url, on: nil, escapeKeyDeletesFile: false)
    case .failure(let error):
        let nsError = error as NSError
        if nsError.domain == "FinderSelectionService" && nsError.code == -2 {
            AlertPresenter.presentWarningWithSettingsButton(
                title: "Automation Permission Required",
                message: "Zoomies needs permission to communicate with Finder.\n\nOpen System Settings → Privacy & Security → Automation, and enable Finder under Zoomies.",
                settingsURL: "x-apple.systempreferences:com.apple.preference.security?Privacy_Automation"
            )
        } else if nsError.domain == "FinderSelectionService" && nsError.code == -3 {
            presentError(title: "Finder didn’t respond", message: nsError.localizedDescription)
        } else {
            presentError(title: "Finder Error", message: error.localizedDescription)
        }
    }
}

